#!/usr/bin/env node
// Summarize Maven Surefire XML reports into a compact Markdown block for an agent's context.
//
// Usage:
//   node .claude/skills/run-tests/scripts/summarize-surefire.mjs [reportsDir] [--since <ISO-8601 time>] [--strict]
//
//   reportsDir  default: sample-app/target/surefire-reports (relative to the current directory)
//   --since     ignore report files last modified before this time (drops stale reports left
//               over from an earlier run, e.g. after running a single test class)
//   --strict    exit 1 when any test failed or errored (for CI); default exit 0 so the summary
//               is always delivered to the caller
//
// Exit codes: 0 summary printed; 1 tests failed (only with --strict); 2 no usable reports found.
//
// Deliberately never prints <system-out>/<system-err>: test logs can contain request data, and
// the summary is meant to be pasted into prompts. Messages are truncated to 300 characters.
// Zero dependencies (Node 22).

import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { join, basename, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const MAX_MESSAGE = 300;

export function decodeEntities(s) {
  return s
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, "&");
}

function attrs(tag) {
  const out = {};
  for (const m of tag.matchAll(/([\w:.-]+)="([^"]*)"/g)) out[m[1]] = decodeEntities(m[2]);
  return out;
}

function oneLine(s, max = MAX_MESSAGE) {
  const flat = s.replace(/\s+/g, " ").trim();
  return flat.length > max ? flat.slice(0, max - 3) + "..." : flat;
}

/** Parse one Surefire TEST-*.xml document. Returns { suite, cases }. */
export function parseSurefireXml(xml) {
  const suiteTag = xml.match(/<testsuite\b[^>]*>/);
  if (!suiteTag) throw new Error("no <testsuite> element");
  const s = attrs(suiteTag[0]);
  const suite = {
    name: s.name ?? "unknown",
    tests: Number(s.tests ?? 0),
    failures: Number(s.failures ?? 0),
    errors: Number(s.errors ?? 0),
    skipped: Number(s.skipped ?? 0),
    time: Number(s.time ?? 0),
  };
  const cases = [];
  // A testcase is either self-closing or has a body (failure/error/skipped/system-out).
  const re = /<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g;
  for (const m of xml.matchAll(re)) {
    const a = attrs(m[1]);
    const body = m[3] ?? "";
    let outcome = "passed";
    let type = "";
    let message = "";
    let at = "";
    const problem = body.match(/<(failure|error)\b([^>]*?)(\/>|>([\s\S]*?)<\/\1>)/);
    if (problem) {
      outcome = problem[1] === "failure" ? "failed" : "error";
      const pa = attrs(problem[2]);
      type = pa.type ?? "";
      const detail = decodeEntities((problem[4] ?? "").replace(/^<!\[CDATA\[|\]\]>$/g, ""));
      message = oneLine(pa.message ?? detail.split("\n")[0] ?? "");
      // First stack frame inside the test class itself gives the failing line.
      const simple = (a.classname ?? "").split(".").pop();
      const frame = detail.split("\n").map((l) => l.trim()).find((l) => simple && l.startsWith("at ") && l.includes(`(${simple}.java:`));
      at = frame ? frame.slice(3) : "";
    } else if (/<skipped\b/.test(body)) {
      outcome = "skipped";
    }
    cases.push({ classname: a.classname ?? suite.name, name: a.name ?? "unknown", time: Number(a.time ?? 0), outcome, type, message, at });
  }
  return { suite, cases };
}

export function loadReports(dir, sinceMs) {
  if (!existsSync(dir)) return { reports: [], skippedStale: 0 };
  const files = readdirSync(dir).filter((f) => /^TEST-.*\.xml$/.test(f)).sort();
  const reports = [];
  let skippedStale = 0;
  for (const f of files) {
    const p = join(dir, f);
    if (sinceMs !== undefined && statSync(p).mtimeMs < sinceMs) {
      skippedStale++;
      continue;
    }
    reports.push({ file: basename(p), ...parseSurefireXml(readFileSync(p, "utf8")) });
  }
  return { reports, skippedStale };
}

export function summarize(reports, { skippedStale = 0 } = {}) {
  const t = { tests: 0, failures: 0, errors: 0, skipped: 0, time: 0 };
  for (const r of reports) for (const k of Object.keys(t)) t[k] += r.suite[k];
  const passed = t.tests - t.failures - t.errors - t.skipped;
  const ok = t.failures === 0 && t.errors === 0;
  const lines = [];
  lines.push(`## Test summary: ${ok ? "PASS" : "FAIL"}`);
  lines.push("");
  lines.push(`${t.tests} tests: ${passed} passed, ${t.failures} failed, ${t.errors} errors, ${t.skipped} skipped (${reports.length} suites, ${t.time.toFixed(1)} s)`);
  if (skippedStale) lines.push(`Ignored ${skippedStale} stale report file(s) older than --since.`);
  lines.push("");
  lines.push("| Suite | Tests | Failed | Errors | Skipped | Time (s) |");
  lines.push("|---|---|---|---|---|---|");
  for (const r of reports) {
    const simple = r.suite.name.split(".").pop();
    lines.push(`| ${simple} | ${r.suite.tests} | ${r.suite.failures} | ${r.suite.errors} | ${r.suite.skipped} | ${r.suite.time.toFixed(2)} |`);
  }
  const bad = reports.flatMap((r) => r.cases.filter((c) => c.outcome === "failed" || c.outcome === "error"));
  if (bad.length) {
    lines.push("");
    lines.push("### Failures");
    bad.forEach((c, i) => {
      const simple = c.classname.split(".").pop();
      lines.push(`${i + 1}. ${simple}.${c.name} (${c.outcome}${c.type ? ", " + c.type : ""})`);
      if (c.message) lines.push(`   message: ${c.message}`);
      if (c.at) lines.push(`   at: ${c.at}`);
    });
  }
  const skipped = reports.flatMap((r) => r.cases.filter((c) => c.outcome === "skipped"));
  if (skipped.length) {
    lines.push("");
    lines.push("### Skipped");
    for (const c of skipped) lines.push(`- ${c.classname.split(".").pop()}.${c.name}`);
  }
  return { ok, text: lines.join("\n") + "\n" };
}

function parseArgs(argv) {
  const opts = { dir: "sample-app/target/surefire-reports", since: undefined, strict: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--strict") opts.strict = true;
    else if (a === "--since") {
      const v = argv[++i];
      const ms = Date.parse(v ?? "");
      if (Number.isNaN(ms)) throw new Error(`--since needs an ISO-8601 time, got: ${v}`);
      opts.since = ms;
    } else if (a.startsWith("--")) throw new Error(`unknown option ${a}`);
    else opts.dir = a;
  }
  return opts;
}

function main() {
  let opts;
  try {
    opts = parseArgs(process.argv.slice(2));
  } catch (e) {
    console.error(`summarize-surefire: ${e.message}`);
    process.exit(2);
  }
  const { reports, skippedStale } = loadReports(opts.dir, opts.since);
  if (reports.length === 0) {
    const why = skippedStale ? `all ${skippedStale} report file(s) are older than --since` : `no TEST-*.xml files in ${opts.dir}`;
    console.log(`## Test summary: NO REPORTS\n\n${why}. The build probably failed before tests ran (compilation error or Maven failure): check the first [ERROR] lines of the Maven output.`);
    process.exit(2);
  }
  const { ok, text } = summarize(reports, { skippedStale });
  process.stdout.write(text);
  process.exit(opts.strict && !ok ? 1 : 0);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) main();

// Tests for summarize-surefire.mjs. Run from AI-SDLC/: node --test .claude/skills/run-tests/scripts/summarize-surefire.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, utimesSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { parseSurefireXml, summarize, loadReports } from "./summarize-surefire.mjs";

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), "summarize-surefire.mjs");

const PASSING = `<?xml version="1.0" encoding="UTF-8"?>
<testsuite name="org.example.fhir.SecurityTest" time="1.033" tests="2" errors="0" skipped="0" failures="0">
  <properties><property name="java.version" value="21"/></properties>
  <testcase name="wrongPasswordIs401" classname="org.example.fhir.SecurityTest" time="0.099">
    <system-out><![CDATA[action=READ resource=Patient/42 user=clinician
]]></system-out>
  </testcase>
  <testcase name="healthEndpointIsPublic" classname="org.example.fhir.SecurityTest" time="0.027"/>
</testsuite>`;

const FAILING = `<?xml version="1.0" encoding="UTF-8"?>
<testsuite name="org.example.fhir.PatientApiTest" time="8.5" tests="4" errors="1" skipped="1" failures="1">
  <testcase name="searchWithoutParametersIs400" classname="org.example.fhir.PatientApiTest" time="0.2">
    <failure message="Status expected:&lt;400&gt; but was:&lt;200&gt;" type="java.lang.AssertionError"><![CDATA[java.lang.AssertionError: Status expected:<400> but was:<200>
	at org.springframework.test.util.AssertionErrors.fail(AssertionErrors.java:61)
	at org.example.fhir.PatientApiTest.searchWithoutParametersIs400(PatientApiTest.java:76)
]]></failure>
    <system-out><![CDATA[Loaded patient Test Patient (MRN MRN-000123)
]]></system-out>
  </testcase>
  <testcase name="readById" classname="org.example.fhir.PatientApiTest" time="0.1">
    <error message="Failed to load ApplicationContext" type="java.lang.IllegalStateException"><![CDATA[java.lang.IllegalStateException: Failed to load ApplicationContext
	at org.springframework.test.context.cache.DefaultCacheAwareContextLoaderDelegate.loadContext(DefaultCacheAwareContextLoaderDelegate.java:180)
]]></error>
  </testcase>
  <testcase name="duplicateMrnIs409" classname="org.example.fhir.PatientApiTest" time="0">
    <skipped/>
  </testcase>
  <testcase name="createReturns201WithLocationAndResource" classname="org.example.fhir.PatientApiTest" time="0.3"/>
</testsuite>`;

function tempReports(files) {
  const dir = mkdtempSync(join(tmpdir(), "surefire-"));
  for (const [name, xml] of Object.entries(files)) writeFileSync(join(dir, name), xml);
  return dir;
}

test("parses suite totals and self-closing and bodied testcases", () => {
  const { suite, cases } = parseSurefireXml(PASSING);
  assert.equal(suite.name, "org.example.fhir.SecurityTest");
  assert.equal(suite.tests, 2);
  assert.deepEqual(cases.map((c) => [c.name, c.outcome]), [["wrongPasswordIs401", "passed"], ["healthEndpointIsPublic", "passed"]]);
});

test("extracts failure message (entity-decoded), type and the test-class stack frame", () => {
  const { cases } = parseSurefireXml(FAILING);
  const f = cases.find((c) => c.name === "searchWithoutParametersIs400");
  assert.equal(f.outcome, "failed");
  assert.equal(f.type, "java.lang.AssertionError");
  assert.equal(f.message, "Status expected:<400> but was:<200>");
  assert.equal(f.at, "org.example.fhir.PatientApiTest.searchWithoutParametersIs400(PatientApiTest.java:76)");
  assert.equal(cases.find((c) => c.name === "readById").outcome, "error");
  assert.equal(cases.find((c) => c.name === "duplicateMrnIs409").outcome, "skipped");
});

test("summary reports FAIL, counts, failures and skipped, and never leaks system-out", () => {
  const reports = [PASSING, FAILING].map((x) => parseSurefireXml(x));
  const { ok, text } = summarize(reports);
  assert.equal(ok, false);
  assert.match(text, /^## Test summary: FAIL/);
  assert.match(text, /6 tests: 3 passed, 1 failed, 1 errors, 1 skipped \(2 suites/);
  assert.match(text, /1\. PatientApiTest\.searchWithoutParametersIs400 \(failed, java\.lang\.AssertionError\)/);
  assert.match(text, /2\. PatientApiTest\.readById \(error, java\.lang\.IllegalStateException\)/);
  assert.match(text, /- PatientApiTest\.duplicateMrnIs409/);
  assert.doesNotMatch(text, /MRN-000123|Loaded patient|Patient\/42/);
});

test("all-green summary says PASS", () => {
  const { ok, text } = summarize([parseSurefireXml(PASSING)]);
  assert.equal(ok, true);
  assert.match(text, /## Test summary: PASS\n\n2 tests: 2 passed, 0 failed/);
});

test("--since drops stale report files", () => {
  const dir = tempReports({ "TEST-a.xml": PASSING, "TEST-b.xml": FAILING });
  const old = new Date("2020-01-01T00:00:00Z");
  utimesSync(join(dir, "TEST-b.xml"), old, old);
  const { reports, skippedStale } = loadReports(dir, Date.parse("2021-01-01T00:00:00Z"));
  assert.equal(reports.length, 1);
  assert.equal(skippedStale, 1);
  rmSync(dir, { recursive: true });
});

test("CLI exit codes: 0 on failures by default, 1 with --strict, 2 without reports", () => {
  const dir = tempReports({ "TEST-b.xml": FAILING, "b.txt": "ignored" });
  const normal = spawnSync(process.execPath, [SCRIPT, dir], { encoding: "utf8" });
  assert.equal(normal.status, 0);
  assert.match(normal.stdout, /Test summary: FAIL/);
  const strict = spawnSync(process.execPath, [SCRIPT, dir, "--strict"], { encoding: "utf8" });
  assert.equal(strict.status, 1);
  const empty = spawnSync(process.execPath, [SCRIPT, join(dir, "missing")], { encoding: "utf8" });
  assert.equal(empty.status, 2);
  assert.match(empty.stdout, /NO REPORTS/);
  const badSince = spawnSync(process.execPath, [SCRIPT, dir, "--since", "yesterday"], { encoding: "utf8" });
  assert.equal(badSince.status, 2);
  rmSync(dir, { recursive: true });
});

#!/usr/bin/env node
// PreToolUse hook for the reviewer subagent (registered in the agent's own frontmatter, see
// docs/tutorials/level-2/examples/reviewer-v1-restricted.md). It lets the reviewer run read-only
// git commands and blocks every other Bash command with exit code 2.
//
// Why a hook: `tools` can only include or exclude the whole Bash tool, and a `disallowedTools`
// entry such as `Bash(git push *)` removes Bash entirely. The hook narrows Bash to a few
// commands, whatever permission mode the parent session is in.
//
// Input: hook JSON on stdin (tool_name, tool_input.command, agent_type, ...).
// Exit 0 = allow the call to continue to normal permission checks. Exit 2 = block; stderr is
// shown to the subagent. Fails closed: unreadable input also exits 2.

import { pathToFileURL } from "node:url";
import { resolve } from "node:path";

const ALLOWED = /^git (diff|log|show|status)( |$)/;
// Shell metacharacters that could chain, redirect or substitute a second command.
const SHELL_META = /[;&|<>`\n\r]|\$\(/;
// git options that write files or run external programs.
const RISKY_OPTIONS = /(^| )(--output(=| |$)|--ext-diff|--textconv|-c )/;

export function decide(input) {
  if (!input || typeof input !== "object") return { allow: false, reason: "hook input is not a JSON object" };
  if (input.tool_name !== "Bash") return { allow: true };
  const raw = String(input.tool_input?.command ?? "");
  if (SHELL_META.test(raw)) return { allow: false, reason: `shell operators are not allowed for the reviewer: ${raw.trim()}` };
  const command = raw.trim().replace(/\s+/g, " ");
  if (!command) return { allow: false, reason: "empty Bash command" };
  if (!ALLOWED.test(command)) {
    return { allow: false, reason: `reviewer may only run git diff, git log, git show or git status; blocked: ${command}` };
  }
  if (RISKY_OPTIONS.test(command)) return { allow: false, reason: `git option not allowed for the reviewer: ${command}` };
  return { allow: true };
}

async function main() {
  let raw = "";
  for await (const chunk of process.stdin) raw += chunk;
  let input;
  try {
    input = JSON.parse(raw);
  } catch {
    process.stderr.write("reviewer-bash-guard: could not parse hook input; blocking\n");
    process.exit(2);
  }
  const { allow, reason } = decide(input);
  if (!allow) {
    process.stderr.write(`reviewer-bash-guard: ${reason}\n`);
    process.exit(2);
  }
  process.exit(0);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) main();

// Tests for reviewer-bash-guard.mjs. Run from AI-SDLC/:
//   node --test docs/tutorials/level-2/examples/reviewer-bash-guard.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { decide } from "./reviewer-bash-guard.mjs";

const HOOK = join(dirname(fileURLToPath(import.meta.url)), "reviewer-bash-guard.mjs");

function run(input) {
  const stdin = typeof input === "string" ? input : JSON.stringify(input);
  return spawnSync(process.execPath, [HOOK], { input: stdin, encoding: "utf8" });
}

function bash(command) {
  return {
    session_id: "test",
    hook_event_name: "PreToolUse",
    permission_mode: "default",
    agent_type: "reviewer",
    tool_name: "Bash",
    tool_input: { command, description: "test" },
  };
}

test("allows read-only git commands", () => {
  for (const c of ["git diff", "git diff HEAD -- sample-app", "git log --oneline -5", "git show HEAD:sample-app/pom.xml", "git status --short"]) {
    assert.equal(decide(bash(c)).allow, true, c);
  }
});

test("blocks non-git and mutating commands", () => {
  for (const c of ["mvn -q -B test", "rm -rf sample-app", "git commit -am wip", "git push", "git checkout -- .", "cat .env", "gitdiff"]) {
    assert.equal(decide(bash(c)).allow, false, c);
  }
});

test("blocks chaining, redirection and substitution", () => {
  for (const c of ["git diff; rm -rf /tmp/x", "git diff && git push", "git diff | tee out.txt", "git diff > review.txt", "git log $(whoami)", "git diff `id`", "git status\nrm x"]) {
    assert.equal(decide(bash(c)).allow, false, c);
  }
});

test("blocks git options that write files or run programs", () => {
  for (const c of ["git diff --output=/tmp/x", "git diff --output /tmp/x", "git diff --ext-diff", "git log --textconv", "git -c core.pager=sh diff"]) {
    assert.equal(decide(bash(c)).allow, false, c);
  }
});

test("ignores other tools", () => {
  assert.equal(decide({ tool_name: "Read", tool_input: { file_path: "sample-app/pom.xml" } }).allow, true);
});

test("process exit codes: 0 allow, 2 block with reason on stderr, 2 on bad JSON", () => {
  assert.equal(run(bash("git diff")).status, 0);
  const blocked = run(bash("git push origin main"));
  assert.equal(blocked.status, 2);
  assert.match(blocked.stderr, /reviewer may only run git diff, git log, git show or git status; blocked: git push origin main/);
  assert.equal(run("not json").status, 2);
});
